#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Candado del ancla: el ancla de un encargo tiene que ser UN SOLO RENGLON,
EXACTO, y aparecer UNA SOLA VEZ en el archivo citado.

Julio, 2026-09-25: cuando se le pega un trozo de codigo al equipo dentro de un
encargo, el ancla tiene que ser UN SOLO RENGLON, exacto, que aparezca UNA sola
vez en el archivo. Con varios renglones la terminal los junta, el texto ya no
coincide y el trabajo se rechaza (paso dos veces ese dia).

Uso:
    echo "<texto de la orden>" | python arnes/candado_ancla.py
    echo '{"orden": "<texto>"}' | python arnes/candado_ancla.py

Salidas:
    0  -> pasa (no hay orden de equipo, o el ancla esta bien, o Julio autorizo)
    2  -> frena: el ancla ocupa mas de un renglon o no aparece exactamente una vez
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path


RAIZ = Path(__file__).resolve().parents[1]

# Marca que dispara el candado: solo actua si el texto pide tocar el equipo.
MARCA_EQUIPO = "ingeniero.py equipo"

# Nombres de archivo del proyecto que aparecen en el texto.
PATRON_ARCHIVO_PY = re.compile(r"[A-Za-z0-9_./\\-]+\.py")

# Arranques que delatan un trozo de codigo.
ARRANQUES_CODIGO = ("if ", "def ", "for ", "return ", "with ", "import ")


def _leer_entrada() -> str:
    """Lee de la entrada el texto de la orden.

    Acepta texto suelto o un JSON con la orden dentro (como los demas candados).
    """
    crudo = sys.stdin.read()
    if not crudo:
        return ""
    texto = crudo.strip()
    if not texto:
        return ""
    # Intento JSON primero: si es un objeto con 'orden' o 'texto', se usa eso.
    if texto.startswith("{"):
        try:
            datos = json.loads(texto)
        except Exception:
            return crudo
        if isinstance(datos, dict):
            for clave in ("orden", "texto", "comando", "command", "input"):
                valor = datos.get(clave)
                if isinstance(valor, str):
                    return valor
        return crudo
    return crudo


def _julio_autorizo() -> bool:
    """Pregunta a arnes/autorizacion.py si Julio autorizo esta orden."""
    try:
        sys.path.insert(0, str(RAIZ))
        from arnes import autorizacion  # type: ignore
    except Exception:
        return False
    for nombre in ("julio_autorizo", "autorizado", "esta_autorizado", "puede_pasar"):
        fn = getattr(autorizacion, nombre, None)
        if callable(fn):
            try:
                return bool(fn())
            except TypeError:
                try:
                    return bool(fn("candado_ancla"))
                except Exception:
                    continue
            except Exception:
                continue
    return False


def _archivos_citados(texto: str) -> list:
    """Saca los nombres de archivo .py que aparecen en el texto."""
    vistos = []
    for m in PATRON_ARCHIVO_PY.finditer(texto):
        ruta = m.group(0)
        if ruta not in vistos:
            vistos.append(ruta)
    return vistos


def _parece_codigo(trozo: str) -> bool:
    """Dice si un trozo parece codigo segun las reglas del encargo."""
    t = trozo.strip()
    if not t:
        return False
    if t.endswith(":"):
        return True
    if "=" in t:
        return True
    if "(" in t or ")" in t:
        return True
    for arranque in ARRANQUES_CODIGO:
        if t.startswith(arranque):
            return True
    return False


def _trozos_codigo(texto: str) -> list:
    """Saca los trozos del texto que parezcan codigo.

    Se parte por renglones y se agrupan los renglones consecutivos que parezcan
    codigo, para poder detectar anclas de varios renglones.
    """
    renglones = texto.splitlines()
    trozos = []
    actual = []
    for renglon in renglones:
        if _parece_codigo(renglon):
            actual.append(renglon)
        else:
            if actual:
                trozos.append("\n".join(actual))
                actual = []
    if actual:
        trozos.append("\n".join(actual))
    return trozos


def _aparece_exactamente_una_vez(trozo: str, archivos: list) -> bool:
    """Comprueba que el trozo aparece exactamente una vez en alguno de los archivos."""
    for ruta in archivos:
        candidatos = [ruta]
        if not Path(ruta).is_absolute():
            candidatos.append(str(RAIZ / ruta))
        for cand in candidatos:
            p = Path(cand)
            if not p.is_file():
                continue
            try:
                contenido = p.read_text(encoding="utf-8", errors="replace")
            except Exception:
                continue
            if contenido.count(trozo) == 1:
                return True
    return False


def _mensaje_freno(trozo: str, archivos: list) -> str:
    """Mensaje en palabras simples, sin jerga, para la salida de error."""
    lineas = [
        "El ancla tiene que ser UN renglon exacto y unico.",
        "",
        "Lo que has pegado ocupa mas de un renglon, o no aparece exactamente una vez",
        "en el archivo del proyecto. Cuando son varios renglones, la terminal los junta",
        "y el texto ya no coincide: el trabajo se rechaza.",
        "",
        "Ancla que has pegado:",
        trozo,
        "",
        "Archivos del proyecto que citas:",
    ]
    if archivos:
        for a in archivos:
            lineas.append("  - " + a)
    else:
        lineas.append("  (ninguno)")
    lineas.append("")
    lineas.append("Como comprobarlo con findstr (una sola linea, exacta, una sola vez):")
    for a in archivos or ["<archivo.py>"]:
        lineas.append('  findstr /n /c:"' + trozo.replace("\n", " ") + '" ' + a)
    lineas.append("")
    lineas.append("Si sale mas de un numero de linea, el ancla no es unica: alargala hasta que lo sea.")
    lineas.append("Si no sale ninguna, el ancla no esta en el archivo: copiala tal cual del archivo.")
    return "\n".join(lineas)


def main() -> int:
    texto = _leer_entrada()
    if MARCA_EQUIPO not in texto:
        return 0
    if _julio_autorizo():
        return 0

    archivos = _archivos_citados(texto)
    trozos = _trozos_codigo(texto)

    for trozo in trozos:
        if "\n" in trozo:
            sys.stderr.write(_mensaje_freno(trozo, archivos) + "\n")
            return 2
        if not _aparece_exactamente_una_vez(trozo, archivos):
            sys.stderr.write(_mensaje_freno(trozo, archivos) + "\n")
            return 2

    return 0


if __name__ == "__main__":
    sys.exit(main())
